export const BUILTIN_FILES: Record<string, string> = {
  "style.yaml": "name: core\nversion: 0.1.0\ndescription: Built-in lawlint style rules.\n",
  "rules/empty-hedge.md": "---\nid: empty-hedge\nengine: inferential\nscope: text\nseverity: warning\ndescription: \"Flags hedges that carry no information about actual uncertainty.\"\nrationale: \"A hedge earns its place only when it tells the reader what is uncertain and why. Stacked qualifiers with no stated reason are AI filler.\"\nmessage: \"This hedge carries no information about actual uncertainty.\"\nexamples:\n  - bad: \"It might be said that the contract is, in some sense, ambiguous.\"\n    good: \"The contract is ambiguous because clause 4 conflicts with clause 9.\"\ngranularity: sentence\n---\nFlag a sentence when it hedges a claim without saying what is uncertain\nor why. Empty hedges sound like: \"it could perhaps be argued that\",\n\"it might be said that\", \"to some extent\", \"in some sense\", \"arguably\"\nwith no reason given, or several qualifiers stacked on one claim.\nDo not flag a sentence that names a concrete source of uncertainty\n(missing evidence, a pending ruling, ongoing treatment, a disputed fact)\nor that states a likelihood together with the reason for it. Do not flag\na plain unhedged claim.\n\n## Flag examples\n- \"It could perhaps be argued that the defendant bears some responsibility for the delay.\"\n- \"To some extent, the outcome may depend on various factors.\"\n- \"It might be said that the contract is, in some sense, ambiguous.\"\n- \"Arguably, there could be certain issues with the evidence presented.\"\n\n## Pass examples\n- \"Damages are uncertain because the plaintiff's treatment is ongoing.\"\n- \"The court will likely deny the motion; three circuits have rejected identical arguments.\"\n- \"We cannot yet value the claim because the appraisal is not complete.\"\n- \"The defendant bears responsibility for the delay.\"\n",
  "rules/no-achievement-language.md": "---\nid: no-achievement-language\nengine: phrase\nscope: text\nintent: style\nseverity: warning\ndescription: \"Flags achievement language and hype in reports, PRs, and docs.\"\nrationale: \"Prose should state what changed and why. Words like “successfully”, “comprehensive”, and “flawless” praise the work instead of describing it, and are the tell of AI-written status updates. Say what happened; let the reader judge it.\"\nmessage: \"Cut the achievement language; state what changed and why.\"\nexamples:\n  - bad: \"Successfully implemented comprehensive error handling to ensure reliable performance.\"\n    good: \"Added error handling to every API endpoint.\"\npatterns:\n  - pattern: '(?i)\\bsuccessfully\\b'\n    message: \"Cut “successfully”; state what changed.\"\n    suggestion: \"Say what happened without the self-praise.\"\n  - pattern: '(?i)\\bcomprehensive(?:ly)?\\b'\n    message: \"Cut “comprehensive”; say what it covers.\"\n    suggestion: \"Name the actual scope.\"\n  - pattern: '(?i)\\breliable\\b|\\breliably\\b'\n    message: \"Cut “reliable”; give the concrete behavior.\"\n    suggestion: \"State what it does and when.\"\n  - pattern: '(?i)\\bflawless(?:ly)?\\b'\n    message: \"Cut “flawless”; describe the result.\"\n    suggestion: \"State the outcome plainly.\"\n  - pattern: '(?i)\\beffortless(?:ly)?\\b'\n    message: \"Cut “effortless”; describe what the user does.\"\n    suggestion: \"State the steps involved.\"\n  - pattern: '(?i)\\bstate[- ]of[- ]the[- ]art\\b'\n    message: \"Cut “state-of-the-art”; say what it is.\"\n    suggestion: \"Describe the actual capability.\"\n  - pattern: '(?i)\\bbest[- ]in[- ]class\\b'\n    message: \"Cut “best-in-class”; give a concrete claim.\"\n    suggestion: \"State a specific, checkable fact.\"\n  - pattern: '(?i)\\bworld[- ]class\\b'\n    message: \"Cut “world-class”; give a concrete claim.\"\n    suggestion: \"State a specific, checkable fact.\"\n  - pattern: '(?i)\\bgame[- ]chang(?:er|ing)\\b'\n    message: \"Cut “game-changing”; say what changed.\"\n    suggestion: \"Describe the concrete effect.\"\n  - pattern: '(?i)\\brevolutionary\\b|\\brevolutioni[sz]e[sd]?\\b'\n    message: \"Cut “revolutionary”; describe the change.\"\n    suggestion: \"State what is new and why it matters.\"\n  - pattern: '(?i)\\btop[- ]notch\\b'\n    message: \"Cut “top-notch”; give a concrete claim.\"\n    suggestion: \"State a specific, checkable fact.\"\n---\n",
  "rules/no-actually-as-filler.md": "---\nid: no-actually-as-filler\nengine: phrase\nscope: text\nseverity: warning\n# Train-split check: the legal-context exception keeps “actually incurred”\n# and similar uses clear of this style lint.\nintent: style\ndescription: \"Flags “actually” when it adds emphasis instead of a fact.\"\nrationale: \"Use “actually” only when it marks a legally relevant fact or correction.\"\nmessage: \"Remove “actually” unless it marks a legally relevant fact.\"\nexamples:\n  - bad: \"The claim is actually weak.\"\n    good: \"The claim is weak.\"\npatterns:\n  - pattern: '(?i)\\bactually\\b'\n    message: \"Remove “actually” unless it marks a legally relevant fact.\"\n    suggestion: \"Delete “actually” unless it marks a legally relevant fact.\"\nallow_context: { pattern: '(?i)\\bactually\\s+(?:incurred|knew|received|paid|suffered|occurred)\\b', window: 48 }\n---\n",
  "rules/no-ai-cliches.md": "---\nid: no-ai-cliches\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags common AI-writing clichés.\"\nrationale: \"Avoid patterns that can make otherwise clear prose sound formulaic or overworked.\"\nmessage: \"Avoid common AI-writing clichés.\"\nexamples:\n  - bad: \"We should delve into this issue.\"\n    good: \"We should examine this issue.\"\npatterns:\n  - pattern: '(?i)\\bdelve\\b'\n    message: \"Avoid the AI-writing cliché “delve”.\"\n    suggestion: \"Use a direct verb such as “examine”.\"\n  - pattern: '(?i)\\btapestry\\b'\n    message: \"Avoid the metaphor “tapestry” in analytical prose.\"\n  - pattern: '(?i)\\blandscape of\\b'\n    message: \"Avoid the vague phrase “landscape of”.\"\n  - pattern: '(?i)\\bin today''s fast-paced world\\b'\n    message: \"Avoid this generic introductory phrase.\"\n  - pattern: '(?i)\\bit is important to note\\b'\n    message: \"State the important point directly.\"\n  - pattern: '(?i)\\bnavigate the complexities\\b'\n    message: \"Use a concrete description of the task or issue.\"\n  - pattern: '(?i)\\bfoster\\b'\n    message: \"Avoid the vague verb “foster”.\"\n    suggestion: \"Name the action or result.\"\n  - pattern: '(?i)\\butilize\\b'\n    message: \"Prefer the plain verb “use”.\"\n    suggestion: \"Use “use”.\"\n  - pattern: '(?i)\\bfacilitate\\b'\n    message: \"Avoid the vague verb “facilitate”.\"\n    suggestion: \"Name what the subject does.\"\n  - pattern: '(?i)\\bempower\\b'\n    message: \"Avoid the vague verb “empower”.\"\n    suggestion: \"State what people can do.\"\n  - pattern: '(?i)\\bstreamline\\b'\n    message: \"Avoid the vague verb “streamline”.\"\n    suggestion: \"Name the step or delay removed.\"\n  - pattern: '(?i)\\bparadigm shift\\b'\n    message: \"Avoid the hype phrase “paradigm shift”.\"\n    suggestion: \"Describe the actual change.\"\n  - pattern: '(?i)\\bgame[- ]changer\\b'\n    message: \"Avoid the hype phrase “game changer”.\"\n    suggestion: \"Describe the concrete effect.\"\n  - pattern: '(?i)\\bthis is huge\\b'\n    message: \"Avoid the hype phrase “this is huge”.\"\n    suggestion: \"State what changed and why it matters.\"\n  - pattern: '(?i)\\bthis changes everything\\b'\n    message: \"Avoid the hype phrase “this changes everything”.\"\n    suggestion: \"Describe the specific consequence.\"\n  - pattern: '(?i)\\bbeacon\\b'\n    message: \"Avoid the vague metaphor “beacon”.\"\n    suggestion: \"State what the subject demonstrates.\"\n  - pattern: '(?i)\\bmulti[- ]faceted\\b'\n    message: \"Avoid the vague adjective “multifaceted”.\"\n    suggestion: \"Name the relevant parts.\"\n  - pattern: '(?i)\\bmeticulous(?:ly)?\\b'\n    message: \"Avoid the praise word “meticulous”.\"\n    suggestion: \"Describe what was checked.\"\n  - pattern: '(?i)\\bintricate\\b'\n    message: \"Avoid the vague adjective “intricate”.\"\n    suggestion: \"Explain the actual complexity.\"\n  - pattern: '(?i)\\bparamount\\b'\n    message: \"Avoid the inflated adjective “paramount”.\"\n    suggestion: \"Say what is most important.\"\n  - pattern: '(?i)\\btransformative\\b'\n    message: \"Avoid the hype adjective “transformative”.\"\n    suggestion: \"Describe the measurable change.\"\n  - pattern: '(?i)\\belevate\\b'\n    message: \"Avoid the vague verb “elevate”.\"\n    suggestion: \"Name the improvement.\"\n  - pattern: '(?i)\\bembark(?:ing)?\\s+on\\b'\n    message: \"Avoid the inflated phrase “embark on”.\"\n    suggestion: \"Use “begin” or name the action.\"\n  - pattern: '(?i)\\bsupercharge\\b'\n    message: \"Avoid the hype verb “supercharge”.\"\n    suggestion: \"Describe the actual improvement.\"\n  - pattern: '(?i)\\bharness\\b'\n    message: \"Avoid the vague verb “harness”.\"\n    suggestion: \"Use a concrete verb such as “use”.\"\n  - pattern: '(?i)\\bever[- ]evolving\\b'\n    message: \"Avoid the vague phrase “ever-evolving”.\"\n    suggestion: \"Name what changed.\"\n---\n",
  "rules/no-anaphoric-openers.md": "---\nid: no-anaphoric-openers\nengine: statistical\nscope: text\nseverity: warning\n# Train-split check: repeated-opener-density above 0.211 fires on 30/165 AI\n# and 12/165 human rows; train AUC 0.8831 is below the 0.9090 baseline.\nintent: style\ndescription: \"Flags repeated sentence openers across a document\"\nmessage: \"Sentence openers repeat too often across the document; vary the openings.\"\nmetric: repeated-opener-density\nthreshold: 0.211\ndirection: above\nexamples:\n  - bad: \"The court reviewed the motion and the supporting record. The court considered the response from both parties. The court examined the affidavits submitted with the motion. The court compared those affidavits with the hearing transcript. The court rejected the unsupported account. The court denied relief on the present record. The court entered judgment for the respondent. The court retained jurisdiction over costs.\"\n    good: \"The court reviewed the motion and the supporting record. It considered the response from both parties, compared the affidavits with the hearing transcript, and rejected the unsupported account. Relief was denied on the present record, and the court retained jurisdiction over costs.\"\n---\n",
  "rules/no-antithesis.md": "---\nid: no-antithesis\nengine: inferential\nscope: text\nseverity: warning\n# Judged train smoke (20 AI / 20 human): flagged 1 AI row and 0 human rows;\n# too few findings to establish a signal, so this remains a style lint.\nintent: style\ndescription: \"Flags rhetorical antithesis that balances one idea against another.\"\nrationale: \"Balanced opposition can make prose sound staged when it replaces a direct statement with a memorable contrast.\"\nmessage: \"State the point directly instead of staging a rhetorical opposition.\"\nexamples:\n  - bad: \"It is not the tool, but the workflow, that determines the result.\"\n    good: \"The workflow determines the result.\"\ngranularity: sentence\n---\nFlag a sentence when it uses balanced opposition as a rhetorical move:\n\"it is X, not Y\", \"less A, more B\", \"not X but Y\", or a similar\nparallel contrast whose main purpose is emphasis rather than precision.\nDo not flag a contrast that carries substantive information, such as\ndistinguishing two legal standards, elements, causes, or remedies. Do not\nflag an ordinary \"but\" clause that simply qualifies or limits a claim.\n\n## Flag examples\n- \"It is not the tool, but the workflow, that determines the result.\"\n- \"The issue is less about the text and more about the remedy.\"\n- \"Not the deadline but the notice controls the analysis.\"\n- \"This is not a question of power; it is a question of judgment.\"\n\n## Pass examples\n- \"The statute applies to employees but not to independent contractors.\"\n- \"The defendant challenges causation, but the record also raises a notice issue.\"\n- \"The rule distinguishes direct damages from consequential damages.\"\n- \"The motion is timely under Rule 12, but the court lacks personal jurisdiction.\"\n",
  "rules/no-binary-contrast.md": "---\nid: no-binary-contrast\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags formulaic binary-contrast constructions.\"\nrationale: \"State the substantive point directly instead of staging a false choice.\"\nmessage: \"State the substantive point directly.\"\nexamples:\n  - bad: \"The question isn't the model. It's the eval.\"\n    good: \"The eval matters more than the model.\"\npatterns:\n  - pattern: '(?i)\\bthe (?:question|problem|issue|point) isn[''’]t\\b[^.?!]{0,80}[.,;]\\s*it[''’]s\\b'\n    message: \"Avoid the binary-contrast setup.\"\n    suggestion: \"State the second point directly.\"\n  - pattern: '(?i)\\bit[''’]s not just\\b[^.?!]{0,80}\\bit[''’]s\\b'\n    message: \"Avoid the binary-contrast setup.\"\n    suggestion: \"State the stronger point directly.\"\n  - pattern: '(?i)\\bthis is not\\b[^.?!]{0,80}\\.\\s*it[''’]s\\b'\n    message: \"Avoid the binary-contrast setup.\"\n    suggestion: \"State the second point directly.\"\n---\n",
  "rules/no-colon-reveal.md": "---\nid: no-colon-reveal\nengine: leading\nscope: text\nseverity: warning\ndescription: \"Flags dramatic colon reveals at sentence starts.\"\nrationale: \"Use colons for lists, labels, and quotes, not staged revelations.\"\nmessage: \"Replace the dramatic colon reveal with a direct sentence.\"\nexamples:\n  - bad: \"The best part: it learns from mistakes.\"\n    good: \"It learns from mistakes.\"\npatterns:\n  - pattern: 'the best part\\s*:'\n    message: \"Replace the dramatic colon reveal with a direct sentence.\"\n    suggestion: \"State the following point directly.\"\n  - pattern: 'the kicker\\s*:'\n    message: \"Replace the dramatic colon reveal with a direct sentence.\"\n    suggestion: \"State the following point directly.\"\n  - pattern: 'the catch\\s*:'\n    message: \"Replace the dramatic colon reveal with a direct sentence.\"\n    suggestion: \"State the following point directly.\"\n  - pattern: 'the result\\s*:'\n    message: \"Replace the dramatic colon reveal with a direct sentence.\"\n    suggestion: \"State the following point directly.\"\n---\n",
  "rules/no-contrasting-pairs.md": "---\nid: no-contrasting-pairs\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags formulaic contrasting pairs\"\nrationale: \"State the quality or limitation directly instead of balancing paired opposites.\"\nmessage: \"State the point directly instead of using a contrasting pair.\"\nexamples:\n  - bad: \"The analysis should be clear without becoming simplistic, balanced without becoming vague.\"\n    good: \"The analysis should be clear and balanced.\"\npatterns:\n  - pattern: '(?i)\\b\\w+(?:\\s+\\w+){0,5}\\s+without\\s+(?:becoming|sounding)\\s+\\w+|\\b\\w+(?:\\s+\\w+){0,5}\\s+without\\s+being\\s+(?:too|overly|unduly|excessively)\\s+\\w+'\n    message: \"Avoid the formulaic contrasting pair.\"\n    suggestion: \"State the quality and its limit directly.\"\n---\n",
  "rules/no-corporate-register-verbs.md": "---\nid: no-corporate-register-verbs\nengine: phrase\nscope: text\nseverity: warning\n# Train-split check: fires on 1/165 AI and 2/165 human rows; the near-zero\n# support and human hit make this a style lint rather than an authorship signal.\nintent: style\ndescription: \"Flags corporate-register verbs\"\nrationale: \"Prefer concrete verbs over corporate language that inflates ordinary actions.\"\nmessage: \"Use a concrete verb instead of corporate-register language.\"\nexamples:\n  - bad: \"The report showcases the team's capabilities.\"\n    good: \"The report shows what the team can do.\"\npatterns:\n  - pattern: '(?i)\\b(?:underscore|showcase(?:s|d)?|spotlight(?:s|ed)?|utilize(?:s|d)?|operationalize(?:s|d)?|incentivize(?:s|d)?)\\b'\n    message: \"Use a concrete verb instead of corporate-register language.\"\n    suggestion: \"Replace it with a direct verb such as “show” or “use”.\"\n  - pattern: '(?i)\\breflect(?:s|ed|ing)?\\s+(?:the\\s+)?(?:commitment|importance|complexity|need|significance)\\b'\n    message: \"Avoid corporate-register uses of “reflect”.\"\n    suggestion: \"State the concrete fact or consequence.\"\n---\n",
  "rules/no-corrective-negation.md": "---\nid: no-corrective-negation\nengine: phrase\nscope: text\nseverity: warning\n# Train-split check: fires on 0/165 AI and 1/165 human rows; the narrow,\n# low-support pattern has no authorship evidence, so this is a style lint.\nintent: style\ndescription: \"Flags corrective-negation constructions\"\nrationale: \"State the substantive point without staging a correction.\"\nmessage: \"State the substantive point directly.\"\nexamples:\n  - bad: \"It's not that the rule is unclear, it's that the record is incomplete.\"\n    good: \"The record is incomplete.\"\npatterns:\n  - pattern: '(?i)\\bit[''’]s\\s+not\\s+that\\b[^.?!]{1,120},\\s*it[''’]s\\b'\n    message: \"Avoid the corrective-negation setup.\"\n    suggestion: \"State the second point directly.\"\n  - pattern: '(?i)\\bthis\\s+isn[''’]t\\s+about\\b[^.?!]{1,120}\\.\\s*it[''’]s\\b'\n    message: \"Avoid the corrective-negation setup.\"\n    suggestion: \"State the substantive point directly.\"\n  - pattern: '(?i)\\bnot\\s+because\\b[^.?!]{1,100}\\bbut\\s+because\\b'\n    message: \"Avoid the corrective-negation setup.\"\n    suggestion: \"State the actual reason directly.\"\n  - pattern: '(?i)\\bless\\s+about\\b[^.?!]{1,100},\\s*more\\s+about\\b'\n    message: \"Avoid the corrective-negation setup.\"\n    suggestion: \"State what the point is about.\"\n---\n",
  "rules/no-dead-metaphors.md": "---\nid: no-dead-metaphors\nengine: phrase\nscope: text\nseverity: warning\nintent: style\ndescription: \"Flags worn-out metaphors and figures of speech.\"\nrationale: \"Orwell's first rule: never use a figure of speech you are used to seeing in print. A dead metaphor no longer calls up an image; it just fills space. State the point plainly.\"\nmessage: \"Replace this worn-out metaphor with a plain statement.\"\nexamples:\n  - bad: \"The settlement was low-hanging fruit for the plaintiff.\"\n    good: \"The plaintiff settled the claim quickly and cheaply.\"\npatterns:\n  - pattern: '(?i)\\blow[- ]hanging fruit\\b'\n    message: \"Avoid the cliché “low-hanging fruit”.\"\n    suggestion: \"Name the easy win directly.\"\n  - pattern: '(?i)\\blevel playing field\\b'\n    message: \"Avoid the cliché “level playing field”.\"\n    suggestion: \"Say what is or is not equal.\"\n  - pattern: '(?i)\\bmove the needle\\b'\n    message: \"Avoid the cliché “move the needle”.\"\n    suggestion: \"State the change you mean.\"\n  - pattern: '(?i)\\bthink(?:ing)? outside the box\\b'\n    message: \"Avoid the cliché “think outside the box”.\"\n    suggestion: \"Describe the new approach.\"\n  - pattern: '(?i)\\bthe elephant in the room\\b'\n    message: \"Avoid the cliché “the elephant in the room”.\"\n    suggestion: \"Name the issue people avoid.\"\n  - pattern: '(?i)\\ba perfect storm\\b'\n    message: \"Avoid the cliché “a perfect storm”.\"\n    suggestion: \"List the causes that combined.\"\n  - pattern: '(?i)\\bwhen push comes to shove\\b'\n    message: \"Avoid the cliché “when push comes to shove”.\"\n    suggestion: \"Say when, or drop it.\"\n  - pattern: '(?i)\\bback to the drawing board\\b'\n    message: \"Avoid the cliché “back to the drawing board”.\"\n    suggestion: \"Say what you will redo.\"\n  - pattern: '(?i)\\btip of the iceberg\\b'\n    message: \"Avoid the cliché “tip of the iceberg”.\"\n    suggestion: \"State how much more there is.\"\n  - pattern: '(?i)\\bpar for the course\\b'\n    message: \"Avoid the cliché “par for the course”.\"\n    suggestion: \"Say that it is usual.\"\n  - pattern: '(?i)\\bhit the ground running\\b'\n    message: \"Avoid the cliché “hit the ground running”.\"\n    suggestion: \"Say what starts, and how fast.\"\n  - pattern: '(?i)\\bthe lion[''’]s share\\b'\n    message: \"Avoid the cliché “the lion’s share”.\"\n    suggestion: \"Use “most” or give the share.\"\n  - pattern: '(?i)\\ba double[- ]edged sword\\b'\n    message: \"Avoid the cliché “a double-edged sword”.\"\n    suggestion: \"Name the upside and the downside.\"\n  - pattern: '(?i)\\bin a nutshell\\b'\n    message: \"Avoid the cliché “in a nutshell”.\"\n    suggestion: \"Just state the summary.\"\n  - pattern: '(?i)\\bthe ball is in (?:your|their|his|her|its) court\\b'\n    message: \"Avoid the cliché “the ball is in your court”.\"\n    suggestion: \"Say who must act next.\"\n---\n",
  "rules/no-doublets.md": "---\nid: no-doublets\nengine: phrase\nscope: text\nseverity: suggestion\ndescription: \"Flags legal doublets and triplets\"\nrationale: \"Avoid patterns that can make otherwise clear prose sound formulaic or overworked.\"\nmessage: \"This legal doublet is often unnecessary.\"\nexamples:\n  - bad: \"The contract is null and void.\"\n    good: \"The contract is void.\"\npatterns:\n  - pattern: '(?i)\\b(?:cease and desist|null and void|any and all)\\b'\n    message: \"This legal doublet is often unnecessary.\"\n    suggestion: \"Use one precise term.\"\n---\n",
  "rules/no-dramatic-fragment.md": "---\nid: no-dramatic-fragment\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags dramatic fragments and negative-listing constructions.\"\nrationale: \"Use complete sentences and state the conclusion without staged fragments.\"\nmessage: \"Replace the dramatic fragment with a direct sentence.\"\nexamples:\n  - bad: \"Not a bug. Not a feature. A policy choice.\"\n    good: \"This is a policy choice.\"\npatterns:\n  - pattern: '(?i)\\bthat[''’]s it\\.\\s*that[''’]s the\\b'\n    message: \"Replace the dramatic fragment with a direct sentence.\"\n    suggestion: \"State the conclusion in one sentence.\"\n  - pattern: '(?i)\\bnot (?:a|an) [^.?!]{1,40}\\.\\s*not (?:a|an)\\b'\n    message: \"Avoid negative-listing fragments.\"\n    suggestion: \"State what the subject is.\"\n  - pattern: '(?i)\\bfull stop\\.'\n    message: \"Cut the dramatic fragment.\"\n    suggestion: \"End the sentence without emphasis.\"\n---\n",
  "rules/no-em-dash-overuse.md": "---\nid: no-em-dash-overuse\nengine: density\nscope: text\nseverity: warning\ndescription: \"Flags excessive em dashes\"\nrationale: \"Use this signal as a prompt to revise rhythm and density, not as a hard prohibition.\"\nmessage: \"Em dashes are used too frequently.\"\nthreshold: 8\nexamples:\n  - bad: \"The court—wisely—paused.\"\n    good: \"The court wisely paused.\"\npatterns:\n  - '—'\n---\n",
  "rules/no-em-dash.md": "---\nid: no-em-dash\nengine: phrase\nscope: text\nseverity: error\n# Train-split check: fires on human prose more often than AI prose (44/222\n# human, 5/222 AI); typography lint, not an authorship signal.\nintent: style\ndescription: \"Flags em dashes\"\nrationale: \"Use commas, parentheses, or a new sentence instead of an em dash.\"\nmessage: \"Avoid em dashes.\"\nexamples:\n  - bad: \"The court—wisely—paused.\"\n    good: \"The court wisely paused.\"\npatterns:\n  - pattern: '—'\n    message: \"Avoid em dashes.\"\n    suggestion: \"Use a comma, parentheses, or a new sentence.\"\n---\n",
  "rules/no-empty-emphasis.md": "---\nid: no-empty-emphasis\nengine: density\nscope: text\nseverity: warning\ndescription: \"Flags overused empty emphasis words\"\nrationale: \"Use this signal as a prompt to revise rhythm and density, not as a hard prohibition.\"\nmessage: \"Replace emphasis with a specific fact or omit it.\"\nthreshold: 12\nexamples:\n  - bad: \"This is very significantly important.\"\n    good: \"This raises damages by forty percent.\"\npatterns:\n  - '(?i)\\b(?:very|really|significantly|crucially)\\b'\n---\n",
  "rules/no-en-dash.md": "---\nid: no-en-dash\nengine: phrase\nscope: text\nseverity: error\n# Train-split check (#38): fires on human prose only (0/5) — typography\n# lint, not an authorship signal.\nintent: style\ndescription: \"Flags en dashes outside numeric ranges.\"\nrationale: \"En dashes belong only in numeric ranges such as 2020–2024. Elsewhere they read as stray punctuation.\"\nmessage: \"Avoid en dashes except in numeric ranges (e.g. 2020–2024).\"\nexamples:\n  - bad: \"The court–ordered remedy failed.\"\n    good: \"The range spans 2020–2024.\"\npatterns:\n  - pattern: '–'\n    message: \"Avoid en dashes except in numeric ranges (e.g. 2020–2024).\"\n    suggestion: \"Use a hyphen, or reword the sentence.\"\n# Old EnDashRule allowed the dash only when a digit sits IMMEDIATELY on each\n# side (no intervening space). A 1-byte window each side of the 3-byte dash\n# reproduces that exactly.\nallow_context: { pattern: '\\d–\\d', window: 1 }\n---\n",
  "rules/no-faux-insight.md": "---\nid: no-faux-insight\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags faux-insight setups that posture before making a claim.\"\nrationale: \"Make the claim stand on its own instead of flattering the writer as the lone expert.\"\nmessage: \"Cut the faux-insight setup and state the claim.\"\nexamples:\n  - bad: \"The part everyone misses: distribution is the real moat.\"\n    good: \"Distribution is the moat.\"\npatterns:\n  - pattern: '(?i)\\bwhat most people get wrong\\b'\n    message: \"Cut the faux-insight setup.\"\n    suggestion: \"State the claim directly.\"\n  - pattern: '(?i)\\bhere[''’]s what nobody tells you\\b'\n    message: \"Cut the faux-insight setup.\"\n    suggestion: \"State the claim directly.\"\n  - pattern: '(?i)\\bthe part everyone misses\\b'\n    message: \"Cut the faux-insight setup.\"\n    suggestion: \"State the claim directly.\"\n  - pattern: '(?i)\\bthis is the part most people skip\\b'\n    message: \"Cut the faux-insight setup.\"\n    suggestion: \"State the claim directly.\"\n  - pattern: '(?i)\\bhere[''’]s the thing\\b'\n    message: \"Cut the faux-insight setup.\"\n    suggestion: \"State the claim directly.\"\n  - pattern: '(?i)\\bhere[''’]s what i mean\\b'\n    message: \"Cut the faux-insight setup.\"\n    suggestion: \"State the claim directly.\"\n  - pattern: '(?i)\\bthe uncomfortable truth is\\b'\n    message: \"Cut the faux-insight setup.\"\n    suggestion: \"State the claim directly.\"\n---\n",
  "rules/no-filler-intensifiers.md": "---\nid: no-filler-intensifiers\nengine: phrase\nscope: text\nseverity: warning\n# Train-split check: fires on human prose at a comparable rate (13/222 human,\n# 15/222 AI); style lint, not an authorship signal.\nintent: style\ndescription: \"Flags filler intensifiers\"\nrationale: \"Remove intensifiers that add emphasis without adding evidence.\"\nmessage: \"Remove the filler intensifier.\"\nexamples:\n  - bad: \"The result is genuinely important.\"\n    good: \"The result is important.\"\npatterns:\n  - pattern: '(?i)\\b(?:genuinely|really|truly)\\b'\n    message: \"Remove the filler intensifier.\"\n    suggestion: \"Delete the intensifier or state the concrete degree.\"\n---\n",
  "rules/no-foreign-phrases.md": "---\nid: no-foreign-phrases\nengine: phrase\nscope: text\nseverity: suggestion\nintent: style\ndescription: \"Flags decorative foreign phrases with an everyday English equivalent.\"\nrationale: \"Orwell's fifth rule: never use a foreign phrase if you can think of an everyday English equivalent. This targets ornamental Latin, not legal terms of art (res judicata, prima facie, habeas corpus, mens rea, stare decisis, de novo), which have no plain substitute.\"\nmessage: \"Use an everyday English equivalent for this foreign phrase.\"\nexamples:\n  - bad: \"The clause covers, inter alia, indemnity and, vis-à-vis the guarantor, notice.\"\n    good: \"The clause covers indemnity and, for the guarantor, notice, among other things.\"\npatterns:\n  - pattern: '(?i)\\binter alia\\b'\n    message: \"Prefer “among other things” over “inter alia”.\"\n    suggestion: \"Use “among other things”.\"\n    fix: \"among other things\"\n  - pattern: '(?i)\\bvis[- ]?à[- ]?vis\\b|\\bvis[- ]a[- ]vis\\b'\n    message: \"Prefer “regarding” or “compared with” over “vis-à-vis”.\"\n    suggestion: \"Use “regarding” or “compared with”.\"\n  - pattern: '(?i)\\bper se\\b'\n    message: \"Prefer “by itself” over “per se”.\"\n    suggestion: \"Use “by itself” or “as such”.\"\n  - pattern: '(?i)\\bipso facto\\b'\n    message: \"Prefer “by that fact” over “ipso facto”.\"\n    suggestion: \"Use “by that fact”.\"\n    fix: \"by that fact\"\n  - pattern: '(?i)\\bmutatis mutandis\\b'\n    message: \"Prefer plain English over “mutatis mutandis”.\"\n    suggestion: \"Use “with the necessary changes”.\"\n    fix: \"with the necessary changes\"\n  - pattern: '(?i)\\bceteris paribus\\b'\n    message: \"Prefer plain English over “ceteris paribus”.\"\n    suggestion: \"Use “all else being equal”.\"\n    fix: \"all else being equal\"\n  - pattern: '(?i)\\bergo\\b'\n    message: \"Prefer “therefore” over “ergo”.\"\n    suggestion: \"Use “therefore”.\"\n    fix: \"therefore\"\n  - pattern: '(?i)\\bad hoc\\b'\n    message: \"Prefer “improvised” or “one-off” over “ad hoc”.\"\n    suggestion: \"Use “improvised” or “one-off”.\"\n---\n",
  "rules/no-hedging.md": "---\nid: no-hedging\nengine: density\nscope: text\nseverity: warning\ndescription: \"Flags excessive hedging language\"\nrationale: \"Use this signal as a prompt to revise rhythm and density, not as a hard prohibition.\"\nmessage: \"Reduce hedging and make the claim more direct.\"\nthreshold: 10\nexamples:\n  - bad: \"Perhaps the claim is arguably strong.\"\n    good: \"The claim is strong.\"\npatterns:\n  - '(?i)\\b(?:arguably|it could be said|generally speaking|perhaps|likely|possibly|somewhat|relatively|to some extent|in many ways|tends to|may well)\\b'\n---\n",
  "rules/no-importance-puffery.md": "---\nid: no-importance-puffery\nengine: phrase\nscope: text\nseverity: error\ndescription: \"Flags inflated claims about importance or status.\"\nrationale: \"State the fact and let the reader judge whether it matters.\"\nmessage: \"State the fact without importance puffery.\"\nexamples:\n  - bad: \"The launch marks a pivotal moment for the company.\"\n    good: \"The launch is the company's first paid product.\"\npatterns:\n  - pattern: '(?i)\\bstands as a testament\\b'\n    message: \"Avoid importance puffery.\"\n    suggestion: \"State the concrete fact.\"\n  - pattern: '(?i)\\ba testament to\\b'\n    message: \"Avoid importance puffery.\"\n    suggestion: \"State what happened.\"\n  - pattern: '(?i)\\bmarks a pivotal moment\\b'\n    message: \"Avoid importance puffery.\"\n    suggestion: \"Name the concrete change.\"\n  - pattern: '(?i)\\bplays a (?:vital|crucial|pivotal) role\\b'\n    message: \"Avoid importance puffery.\"\n    suggestion: \"Describe the actual function.\"\n  - pattern: '(?i)\\bsolidifies its position\\b'\n    message: \"Avoid importance puffery.\"\n    suggestion: \"State the concrete result.\"\n  - pattern: '(?i)\\bunderscores (?:its significance|the importance)\\b'\n    message: \"Avoid importance puffery.\"\n    suggestion: \"State the fact directly.\"\n---\n",
  "rules/no-landing-sentence.md": "---\nid: no-landing-sentence\nengine: inferential\nscope: text\nseverity: warning\n# Judged train smoke (20 AI / 20 human): flagged 0 AI and 0 human rows;\n# unmeasured support, so this remains a style lint.\nintent: style\ndescription: \"Flags short closing sentences written for rhetorical effect.\"\nrationale: \"A punchy closer can perform finality without stating a holding or consequence.\"\nmessage: \"Replace the rhetorical closer with the concrete holding or consequence.\"\nexamples:\n  - bad: \"The record contains no evidence of delivery. That's the whole game.\"\n    good: \"The record contains no evidence of delivery. The notice was therefore ineffective.\"\ngranularity: paragraph\n---\nFlag a short final sentence written mainly to create a punchy sense of\nfinality, such as \"that's the whole game\", \"nothing else matters\", or\n\"end of story\". The sentence should be rhetorical rather than informative.\nDo not flag a short sentence that states a real holding, amount, deadline,\nor other material fact. Do not flag a concise conclusion merely because it\nends a paragraph.\n\n## Flag examples\n- \"The record contains no evidence of delivery. That's the whole game.\"\n- \"The agency never made the required finding. Nothing else matters.\"\n- \"The clause has no exception. End of story.\"\n- \"The witness changed her account three times. That settles it.\"\n\n## Pass examples\n- \"The record contains no evidence of delivery. The notice was therefore ineffective.\"\n- \"The agency never made the required finding. The order must be vacated.\"\n- \"The clause has no exception. It applies to this claim.\"\n- \"The witness changed her account three times. The court found her testimony unreliable.\"\n",
  "rules/no-legalese.md": "---\nid: no-legalese\nengine: phrase\nscope: text\nseverity: warning\nintent: style\ndescription: \"Flags archaic or unnecessarily formal legalese.\"\nrationale: \"Avoid patterns that can make otherwise clear prose sound formulaic or overworked.\"\nmessage: \"Avoid archaic legalese.\"\nexamples:\n  - bad: \"Pursuant to the agreement, the fee is due.\"\n    good: \"Under the agreement, the fee is due.\"\npatterns:\n  - pattern: '(?i)\\bhereinafter\\b'\n    message: \"Avoid “hereinafter”.\"\n    suggestion: \"Name the party or concept directly.\"\n  - pattern: '(?i)\\baforementioned\\b'\n    message: \"Avoid “aforementioned”.\"\n    suggestion: \"Repeat the noun or use a clear reference.\"\n  - pattern: '(?i)\\bpursuant to\\b'\n    message: \"Consider replacing “pursuant to”.\"\n    suggestion: \"Use “under” or “by”.\"\n    fix: \"under\"\n  - pattern: '(?i)\\bnotwithstanding the foregoing\\b'\n    message: \"Avoid “notwithstanding the foregoing”.\"\n    suggestion: \"State the exception directly.\"\n    fix: \"despite the foregoing\"\n  - pattern: '(?i)\\bherein\\b|\\bthereto\\b'\n    message: \"Avoid archaic legalese.\"\n    suggestion: \"Use a specific noun or pronoun.\"\n---\n",
  "rules/no-marketing-language.md": "---\nid: no-marketing-language\nengine: phrase\nscope: text\nseverity: error\ndescription: \"Flags marketing language, hype, and filler.\"\nrationale: \"Avoid patterns that can make otherwise clear prose sound formulaic or overworked.\"\nmessage: \"Avoid marketing language, hype, and filler.\"\nexamples:\n  - bad: \"We leverage a robust platform.\"\n    good: \"We rely on a dependable platform.\"\npatterns:\n  - pattern: '(?i)\\bleverage\\b'\n    message: \"Avoid the marketing verb “leverage”.\"\n    suggestion: \"Use “use” or a concrete verb.\"\n  - pattern: '(?i)\\bunlock\\b'\n    message: \"Avoid the hype verb “unlock”.\"\n    suggestion: \"Describe the actual outcome.\"\n  - pattern: '(?i)\\bpowerful\\b'\n    message: \"Avoid the filler adjective “powerful”.\"\n    suggestion: \"State the specific capability.\"\n  - pattern: '(?i)\\bseamless(?:ly)?\\b'\n    message: \"Avoid the hype word “seamless”.\"\n    suggestion: \"Describe what actually happens.\"\n  - pattern: '(?i)\\brobust\\b'\n    message: \"Avoid the filler adjective “robust”.\"\n    suggestion: \"Name the concrete property.\"\n  - pattern: '(?i)\\bcutting[- ]edge\\b'\n    message: \"Avoid the hype phrase “cutting-edge”.\"\n    suggestion: \"Say what it is.\"\n  - pattern: '(?i)\\bdelve\\b'\n    message: \"Avoid “delve”.\"\n    suggestion: \"Use a direct verb such as “examine”.\"\n  - pattern: '(?i)\\btapestry\\b'\n    message: \"Avoid the metaphor “tapestry”.\"\n  - pattern: '(?i)\\bin the realm of\\b'\n    message: \"Avoid “in the realm of”.\"\n    suggestion: \"Name the subject directly.\"\n  - pattern: '(?i)\\bnavigate the landscape of\\b'\n    message: \"Avoid “navigate the landscape of”.\"\n    suggestion: \"Describe the task.\"\n  - pattern: '(?i)\\bit[''’]s worth noting that\\b'\n    message: \"State the point directly.\"\n    suggestion: \"Drop the throat-clearing.\"\n  - pattern: '(?i)\\bat the end of the day\\b'\n    message: \"Avoid the filler phrase “at the end of the day”.\"\n---\n",
  "rules/no-metronomic-cadence.md": "---\nid: no-metronomic-cadence\nengine: statistical\nscope: text\nseverity: suggestion\n# Train-split check: cadence-autocorrelation above -0.306 fires on 133/165 AI\n# and 125/165 human rows; train AUC 0.8719 is below the 0.9090 baseline.\nintent: style\ndescription: \"Flags predictable sentence-length cadence\"\nmessage: \"Sentence lengths follow a predictable cadence; vary the rhythm.\"\n# The metric remains useful as a drafting signal, but not as an authorship\n# signal.\nmetric: cadence-autocorrelation\nthreshold: -0.306\ndirection: above\nexamples:\n  - bad: \"The court reviewed the record. The parties filed their briefs today. The clerk entered the order after the hearing. Counsel must comply with the judgment. The court considered each disputed fact in the record. The parties may renew the motion after discovery. The clerk shall serve the order on counsel. Counsel shall comply with the order.\"\n    good: \"The court reviewed the motion. After extensive briefing, the record, including three depositions and two expert reports, still contains disputed facts that cannot be resolved on paper. Summary judgment is denied.\"\n---\n",
  "rules/no-negative-parallelism.md": "---\nid: no-negative-parallelism\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags repeated negative parallelism\"\nrationale: \"Use a direct statement instead of a chain of negative fragments.\"\nmessage: \"Replace the repeated negative structure with a direct statement.\"\nexamples:\n  - bad: \"No delay. No explanation. No remedy.\"\n    good: \"The record shows no delay, explanation, or remedy.\"\npatterns:\n  - pattern: '(?i)\\bno\\s+[^.!?]{1,70}[.!?]\\s*no\\s+'\n    message: \"Avoid repeated “No …” openers.\"\n    suggestion: \"Combine the points in a direct sentence.\"\n  - pattern: '(?i)\\bnot\\s+[^,.;!?]{1,45},\\s*not\\s+'\n    message: \"Avoid repeated “Not …” structure.\"\n    suggestion: \"State the positive point directly.\"\n  - pattern: '(?i)\\bnever\\s+[^;.!?]{1,55};\\s*never\\s+'\n    message: \"Avoid repeated “Never …” structure.\"\n    suggestion: \"State the rule or fact directly.\"\n---\n",
  "rules/no-nominalization.md": "---\nid: no-nominalization\nengine: density\nscope: text\nseverity: warning\n# Train-split density sweep: threshold 1 fires on 0/222 AI and 9/222 human\n# rows; style lint because this construction is more common in human prose.\nintent: style\ndescription: \"Flags weak verbs paired with nominalized nouns\"\nrationale: \"Use the plain verb when it makes the sentence shorter and clearer.\"\nmessage: \"Prefer the plain verb to a weak verb plus nominalized noun.\"\nthreshold: 1\nexamples:\n  - bad: \"The court made a determination about the claim.\"\n    good: \"The court determined the claim.\"\npatterns:\n  - '(?i)\\b(?:make|made|makes|provide|provided|provides|conduct|conducted|conducts|perform|performed|performs|carry\\s+out|carried\\s+out|reach|reached|undertake|undertook)\\s+(?:a|an|the)?\\s*(?:\\w+\\s+){0,2}(?:determination|explanation|assessment|evaluation|implementation|investigation|analysis|decision|consideration|recommendation|conversation|discussion)\\b'\n---\n",
  "rules/no-not-only.md": "---\nid: no-not-only\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags not-only/but-also constructions\"\nrationale: \"Avoid patterns that can make otherwise clear prose sound formulaic or overworked.\"\nmessage: \"Avoid the formulaic “not only ... but also” construction.\"\nexamples:\n  - bad: \"The ruling was not only wrong but also harmful.\"\n    good: \"The ruling was wrong and harmful.\"\npatterns:\n  - pattern: '(?is)\\bnot only\\b[\\s\\S]{0,120}\\bbut also\\b'\n    message: \"Avoid the formulaic “not only ... but also” construction.\"\n---\n",
  "rules/no-paired-phrasing.md": "---\nid: no-paired-phrasing\nengine: statistical\nscope: text\nseverity: suggestion\n# Train-split check: paired-adjective-rate above 4.124 fires on 156/165 AI\n# and 131/165 human rows; train AUC 0.8924 is below the 0.9090 baseline.\nintent: style\ndescription: \"Flags excessive paired phrasing\"\nmessage: \"Coordinate and contrasting pairs occur too often; vary the phrasing.\"\nmetric: paired-adjective-rate\nthreshold: 4.124\ndirection: above\nexamples:\n  - bad: \"The court sought clear and consistent rules for the parties. The parties offered careful and measured arguments about the record. The order should be fair and practical for everyone involved. The briefing presented precise and detailed objections to the proposed remedy. The witnesses gave calm and credible accounts during the hearing.\"\n    good: \"The court sought clear rules for the parties. The parties offered measured arguments about the record. The order should work in practice. The briefing presented detailed objections to the proposed remedy. The witnesses gave credible accounts during the hearing.\"\n---\n",
  "rules/no-paragraph-pinning.md": "---\nid: no-paragraph-pinning\nengine: inferential\nscope: text\nseverity: warning\n# Judged train smoke (20 AI / 20 human): flagged 0 AI and 0 human rows;\n# unmeasured support, so this remains a style lint.\nintent: style\ndescription: \"Flags paragraphs that open and close by repeating the same theme.\"\nrationale: \"Returning to the opening phrase as a closing beat pins the paragraph instead of moving the analysis forward.\"\nmessage: \"End the paragraph with its consequence or next point, not its opening theme.\"\nexamples:\n  - bad: \"The record raises a notice problem. The parties exchanged several letters, but none stated the contractual deadline. The notice problem therefore remains the notice problem.\"\n    good: \"The record raises a notice problem. The parties exchanged several letters, but none stated the contractual deadline. The court should therefore construe the notice provision against the drafter.\"\ngranularity: paragraph\n---\nFlag a paragraph when its opening theme or distinctive phrase returns in\nthe closing sentence merely to pin the paragraph's point. The return may\nrepeat the same words or restate the same idea without adding a consequence,\nqualification, or new direction. Do not flag a paragraph that ends with a\nnew implication, result, or recommendation. Do not flag repetition required\nto identify a defined legal term, party, claim, or statutory element.\n\n## Flag examples\n- \"The record presents a serious timing problem. The parties dispute when the notice arrived, and the file contains no delivery receipt. The timing problem remains the timing problem.\"\n- \"The statute gives the agency broad discretion. The agency considered the relevant reports and heard from both sides. That broad discretion is the central point.\"\n- \"The contract contains an integration clause. The parties exchanged drafts and signed the final version. The integration clause is still the integration clause.\"\n- \"The witness's account is uncertain. She changed the date twice and could not identify the source of her estimate. The uncertainty is the real issue.\"\n\n## Pass examples\n- \"The record presents a serious timing problem. The parties dispute when the notice arrived, and the file contains no delivery receipt. The court should remand for a finding on delivery.\"\n- \"The statute gives the agency broad discretion. The agency considered the relevant reports and heard from both sides. The decision therefore falls within the statute's zone of reasonableness.\"\n- \"The contract contains an integration clause. The parties exchanged drafts and signed the final version. The clause bars reliance on the earlier representations.\"\n- \"The witness's account is uncertain. She changed the date twice and could not identify the source of her estimate. The testimony cannot support summary judgment.\"\n",
  "rules/no-parallel-sentence-structure.md": "---\nid: no-parallel-sentence-structure\nengine: inferential\nscope: text\nseverity: warning\n# Judged train smoke (20 AI / 20 human): flagged 0 AI and 3 human rows;\n# human firing makes this a style lint.\nintent: style\ndescription: \"Flags repeated syntactic templates across sentences in a paragraph.\"\nrationale: \"Repeated sentence templates can make a paragraph sound metronomic even when its words change.\"\nmessage: \"Vary the sentence structure within this paragraph.\"\nexamples:\n  - bad: \"The court reviewed the motion. The court considered the response. The court rejected the argument.\"\n    good: \"After reviewing the motion and response, the court rejected the argument.\"\ngranularity: paragraph\n---\nFlag a paragraph when two or more sentences rely on the same syntactic\ntemplate for emphasis, such as repeated subject-verb openings, repeated\n\"the X is...\" clauses, or repeated imperative forms. The repetition must\nshape the paragraph's rhythm, not merely result from a shared legal term.\nDo not flag parallelism inside one enumerated list, a statutory recitation,\na quoted provision, or another context where the repeated structure is\ncorrect and functional. Do not flag ordinary repetition of a party's name\nor a defined term when the surrounding sentence structures differ.\n\n## Flag examples\n- \"The court reviewed the motion. The court considered the response. The court rejected the argument.\"\n- \"The agency found that the report was late. The agency found that the notice was incomplete. The agency found that the appeal was barred.\"\n- \"The contract requires notice. The contract requires payment. The contract requires arbitration.\"\n- \"The witness said she saw the car. The witness said she heard the impact. The witness said she called 911.\"\n\n## Pass examples\n- \"After reviewing the motion and response, the court rejected the argument.\"\n- \"The agency found that the report was late, concluded that notice was incomplete, and dismissed the appeal.\"\n- \"The contract requires notice and payment; it also requires arbitration.\"\n- \"The witness saw the car, heard the impact, and called 911.\"\n",
  "rules/no-parataxis.md": "---\nid: no-parataxis\nengine: inferential\nscope: text\nseverity: warning\n# Judged train smoke (20 AI / 20 human): flagged 0 AI and 0 human rows;\n# unmeasured support, so this remains a style lint.\nintent: style\ndescription: \"Flags marches of short coordinate clauses and sentences.\"\nrationale: \"A string of equal short clauses can create a mechanical rhythm when the relationships between ideas deserve subordination.\"\nmessage: \"Join or subordinate these short clauses so their relationship is clear.\"\nexamples:\n  - bad: \"The court read the contract. It reviewed the emails. It considered the testimony. It denied the motion.\"\n    good: \"After reviewing the contract, emails, and testimony, the court denied the motion.\"\ngranularity: paragraph\n---\nFlag a paragraph when it marches through several short coordinate clauses\nor sentences, especially repeated \"and\" clauses, without showing which idea\ncauses, limits, or supports another. Look for a mechanical sequence rather\nthan a single concise sentence. Do not flag deliberately short holdings,\noperative commands, or citation sentences when their brevity is normal for\nlegal prose. Do not flag a paragraph whose short sentences each carry a\ndistinct legal step or whose coordination makes the relationship clear.\n\n## Flag examples\n- \"The court reviewed the motion. It read the response. It checked the docket. It set a hearing.\"\n- \"The witness arrived and she sat and she waited and she testified.\"\n- \"The agency issued the rule. It took comments. It changed the text. It published the rule.\"\n- \"The contract says payment is due. It sets a date. It states a place. It gives a remedy.\"\n\n## Pass examples\n- \"The court denied the motion because the response was untimely.\"\n- \"The court held that the notice was late. The judgment followed.\"\n- \"The clerk entered judgment. See Fed. R. Civ. P. 58.\"\n- \"The agency issued the rule, accepted comments, revised the text, and published the final version.\"\n",
  "rules/no-parenthetical-asides.md": "---\nid: no-parenthetical-asides\nengine: density\nscope: text\nseverity: warning\nintent: style\ndescription: \"Flags frequent parenthetical asides\"\nrationale: \"Use this signal as a prompt to revise rhythm and density, not as a hard prohibition.\"\nmessage: \"Parenthetical asides appear frequently; integrate important clauses into the sentence.\"\nthreshold: 15\nexamples:\n  - bad: \"The court (again) delayed (twice).\"\n    good: \"The court delayed again, twice.\"\n  - bad: \"The remedy (which the court ordered) failed.\"\n    good: \"Under Section 4(b), the court-ordered remedy failed.\"\n# A paren group attached directly to the preceding token is a statutory\n# subdivision reference (Section 4(b), 12(a)(1)), not an aside — only count\n# groups that follow whitespace or start the text. The capture group marks\n# the aside itself; the consumed leading whitespace must not enter the span.\npatterns:\n  - '(?:^|\\s)(\\([^)]*\\))'\n---\n",
  "rules/no-passive-overuse.md": "---\nid: no-passive-overuse\nengine: density\nscope: text\nseverity: warning\ndescription: \"Flags likely passive-voice overuse\"\nrationale: \"Use this signal as a prompt to revise rhythm and density, not as a hard prohibition.\"\nmessage: \"Passive voice appears frequently; prefer active constructions where possible.\"\nthreshold: 25\nexamples:\n  - bad: \"The motion was denied by the court.\"\n    good: \"The court denied the motion.\"\npatterns:\n  - '(?i)\\b(?:is|are|was|were|be|been|being)\\s+\\w+(?:ed|en)\\b'\n---\n",
  "rules/no-performed-enthusiasm.md": "---\nid: no-performed-enthusiasm\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags performed enthusiasm\"\nrationale: \"Use a factual description instead of performed affect.\"\nmessage: \"Replace performed enthusiasm with a concrete statement.\"\nexamples:\n  - bad: \"We are thrilled to announce the new filing system.\"\n    good: \"The new filing system is available.\"\npatterns:\n  - pattern: '(?i)\\b(?:excited|thrilled)\\s+to\\b'\n    message: \"Avoid performed enthusiasm.\"\n    suggestion: \"State what happened or what is available.\"\n  - pattern: '(?i)\\bwe[''’]re\\s+pumped\\b'\n    message: \"Avoid performed enthusiasm.\"\n    suggestion: \"State the concrete result.\"\n  - pattern: '(?i)\\bcan[''’]t\\s+wait\\b'\n    message: \"Avoid performed enthusiasm.\"\n    suggestion: \"Give the relevant date or action.\"\n  - pattern: '(?i)\\blove\\s+(?:this|that)\\b'\n    message: \"Avoid performed enthusiasm.\"\n    suggestion: \"Describe the specific benefit.\"\n---\n",
  "rules/no-repetitive-openers.md": "---\nid: no-repetitive-openers\nengine: statistical\nscope: text\nseverity: warning\ndescription: \"Flags repeated sentence openings.\"\nmessage: \"Three consecutive sentences begin with the same word.\"\nmetric: repetitive-openers\nparams: { run_length: 3 }\nexamples:\n  - bad: \"The court erred. The record shows this plainly. The remedy is reversal.\"\n    good: \"The court erred. Its record shows this plainly. Reversal is the remedy.\"\n---\n",
  "rules/no-rhetorical-setups.md": "---\nid: no-rhetorical-setups\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags rhetorical setups that delay the substantive point.\"\nrationale: \"Make the point directly instead of staging a reveal for the reader.\"\nmessage: \"Cut the rhetorical setup and state the point.\"\nexamples:\n  - bad: \"What if I told you the filing deadline already passed?\"\n    good: \"The filing deadline already passed.\"\npatterns:\n  - pattern: '(?i)\\bwhat if i told you\\b'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"State the point directly.\"\n  - pattern: '(?i)\\bthink about it\\s*:'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"State the implication directly.\"\n  - pattern: '(?i)\\bplot twist\\s*:'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"State the twist as a fact.\"\n  - pattern: '(?i)\\blet that sink in\\b'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"End with the point.\"\n  - pattern: '(?i)\\bread that again\\b'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"State the point once.\"\n  - pattern: '(?i)\\bmake no mistake\\b'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"State the point directly.\"\n  - pattern: '(?i)\\bto be clear\\b'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"State the clarification directly.\"\n  - pattern: '(?i)\\blet[''’]s be honest\\b'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"State the relevant fact directly.\"\n  - pattern: '(?i)\\bhere[''’]s the reality\\b'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"State the point directly.\"\n  - pattern: '(?i)\\band that[''’]s the point\\b'\n    message: \"Cut the rhetorical setup.\"\n    suggestion: \"State the point directly.\"\n---\n",
  "rules/no-robotic-transitions.md": "---\nid: no-robotic-transitions\nengine: density\nscope: text\nseverity: warning\ndescription: \"Flags overuse of formulaic transitions\"\nrationale: \"Use this signal as a prompt to revise rhythm and density, not as a hard prohibition.\"\nmessage: \"Formulaic sentence transitions are overused.\"\nthreshold: 18\nexamples:\n  - bad: \"Moreover, the claim fails.\"\n    good: \"The claim also fails.\"\npatterns:\n  - '(?im)^\\s*(Moreover|Furthermore|Additionally|In conclusion),'\n---\n",
  "rules/no-rule-of-three.md": "---\nid: no-rule-of-three\nengine: density\nscope: text\nseverity: warning\ndescription: \"Flags dense repeated triplet constructions\"\nrationale: \"Use this signal as a prompt to revise rhythm and density, not as a hard prohibition.\"\nmessage: \"Repeated rule-of-three constructions can sound formulaic.\"\nthreshold: 12\nexamples:\n  - bad: \"The rule is clear, simple, and fair. The test is direct, narrow, and workable. The remedy is prompt, complete, and final. The record is old, incomplete, and unreliable. The briefing is careful, detailed, and extensive. The result is stable, predictable, and fair. The order is coherent, practical, and durable.\"\n    good: \"The rule is clear and fair.\"\npatterns:\n  - '(?i)\\b\\w+(?:\\s+\\w+){0,3},\\s+\\w+(?:\\s+\\w+){0,3},\\s+and\\s+\\w+'\n---\n",
  "rules/no-semicolons.md": "---\nid: no-semicolons\nengine: phrase\nscope: text\nseverity: error\nintent: style\ndescription: \"Flags semicolons.\"\nrationale: \"Avoid patterns that can make otherwise clear prose sound formulaic or overworked.\"\nmessage: \"Prefer periods over semicolons.\"\nexamples:\n  - bad: \"The motion failed; the court adjourned.\"\n    good: \"The motion failed. The court adjourned.\"\npatterns:\n  - pattern: ';'\n    message: \"Prefer periods over semicolons.\"\n    suggestion: \"Two short sentences beat one stitched-together one.\"\n---\n",
  "rules/no-setup-payoff.md": "---\nid: no-setup-payoff\nengine: inferential\nscope: text\nseverity: warning\n# Judged train smoke (20 AI / 20 human): flagged 0 AI and 0 human rows;\n# unmeasured support, so this remains a style lint.\nintent: style\ndescription: \"Flags staged questions or tensions resolved by the next sentence.\"\nrationale: \"A setup followed by a manufactured payoff delays a direct point for dramatic effect.\"\nmessage: \"State the substantive point without staging a question or tension.\"\nexamples:\n  - bad: \"What does the record show? It shows that the notice was late.\"\n    good: \"The record shows that the notice was late.\"\ngranularity: paragraph\n---\nFlag a paragraph when one sentence poses a rhetorical question, announces\na tension, or creates suspense solely so the next sentence can resolve it\nwith an obvious restatement. The setup and payoff should function as one\ndirect claim. Do not flag a genuine question that frames an issue the text\nthen answers with evidence, analysis, or a disputed legal standard. Do not\nflag a transition that introduces a genuinely new section or issue.\n\n## Flag examples\n- \"What does the record show? It shows that the notice was late.\"\n- \"The question is simple: who had notice? The answer is the agency.\"\n- \"This raises a serious point. The point is that the contract is unclear.\"\n- \"Why does that matter? It matters because the claim is untimely.\"\n\n## Pass examples\n- \"What does the record show about delivery? The receipt is missing, and the witness disputes the date.\"\n- \"The question is whether the agency had notice before the deadline. The answer turns on the March 3 email.\"\n- \"The record raises a serious point: the contract uses two different dates for payment.\"\n- \"Why does that matter? Because the statute makes timely notice a condition of review.\"\n",
  "rules/no-stacked-noun-phrases.md": "---\nid: no-stacked-noun-phrases\nengine: density\nscope: text\nseverity: warning\n# Train-split density sweep: threshold 4 fires on 11/222 AI and 17/222 human\n# rows; comparable human rate makes this a style lint.\nintent: style\ndescription: \"Flags stacked noun phrases before abstract head nouns\"\nrationale: \"Unpack dense noun stacks so the relationship between ideas is explicit.\"\nmessage: \"Unpack the stacked noun phrase.\"\nthreshold: 4\npatterns:\n  - '(?i)\\b(?:[a-z][a-z-]+\\s+){2,}(?:strategy|framework|process|solution|initiative|approach|capability|infrastructure|methodology|program)\\b'\nexamples:\n  - bad: \"The agency adopted a long-term claims processing framework.\"\n    good: \"The agency adopted a framework for processing claims over the long term.\"\n---\n",
  "rules/no-summary-beat.md": "---\nid: no-summary-beat\nengine: inferential\nscope: text\nseverity: warning\n# Judged train smoke (20 AI / 20 human): flagged 0 AI and 0 human rows;\n# unmeasured support, so this remains a style lint.\nintent: style\ndescription: \"Flags closing sentences that recap a paragraph without adding information.\"\nrationale: \"A summary beat announces the paragraph's point after the analysis is complete instead of carrying the analysis forward.\"\nmessage: \"Remove the closing summary beat or replace it with a consequence.\"\nexamples:\n  - bad: \"The notice omitted the required date, so the agency could not verify when the appeal period began. The upshot is simple.\"\n    good: \"The notice omitted the required date, so the agency could not verify when the appeal period began. The appeal was therefore timely.\"\ngranularity: paragraph\n---\nFlag a paragraph's closing sentence when it merely recaps the paragraph\nwith a phrase such as \"the upshot is simple\", \"that is the point\", \"the\nlesson is clear\", or \"this is the tension\", without adding a fact, result,\nqualification, or next step. Do not flag a conclusion that adds a concrete\nholding, consequence, number, exception, or recommendation. Do not flag\npadded elaboration merely because a sentence follows another one: padded\nelaboration restates the previous sentence, while a summary beat recaps\nthe paragraph as a whole.\n\n## Flag examples\n- \"The notice omitted the required date, and the agency could not verify when the appeal period began. The upshot is simple.\"\n- \"The parties disputed the clause's meaning, and the court adopted the narrower reading. That is the point.\"\n- \"The record contains conflicting accounts and no neutral witness. That is the tension.\"\n- \"The rule has exceptions, but none applies here. The lesson is clear.\"\n\n## Pass examples\n- \"The notice omitted the required date, and the agency could not verify when the appeal period began. The appeal was therefore timely.\"\n- \"The parties disputed the clause's meaning, and the court adopted the narrower reading. That reading excludes consequential damages.\"\n- \"The record contains conflicting accounts and no neutral witness. The court should resolve the dispute at trial.\"\n- \"The rule has exceptions, but none applies here. The motion is denied.\"\n",
  "rules/no-superficial-analysis.md": "---\nid: no-superficial-analysis\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags trailing participial clauses that pretend to explain significance.\"\nrationale: \"Replace vague analysis with the concrete consequence or reason.\"\nmessage: \"Replace the vague analysis with a concrete consequence.\"\nexamples:\n  - bad: \"The launch adds file search, highlighting the team's commitment to better workflows.\"\n    good: \"The launch adds file search, so users can find old drafts without leaving the editor.\"\npatterns:\n  - pattern: '(?i),\\s*(?:highlighting|underscoring|reflecting|showcasing|signaling|demonstrating|emphasizing|illustrating)\\b\\s+(?:the|its|their|a|how)\\b'\n    message: \"Replace the vague analysis with a concrete consequence.\"\n    suggestion: \"State what the change does or why it matters.\"\n---\n",
  "rules/no-sycophantic-openers.md": "---\nid: no-sycophantic-openers\nengine: leading\nscope: text\nseverity: error\ndescription: \"Flags sycophantic openers\"\nrationale: \"Start with the substance. Openers that add no information should be cut.\"\nmessage: \"Skip the sycophantic opener and start with the substance.\"\nexamples:\n  - bad: \"Great question. The statute controls.\"\n    good: \"The statute controls.\"\npatterns:\n  - pattern: '(?:great|good|excellent|fantastic|wonderful) question'\n    message: \"Skip the sycophantic opener and start with the substance.\"\n    suggestion: \"Skip the sycophantic opener and start with the substance.\"\n  - pattern: 'what a (?:great|fascinating|wonderful|excellent|interesting) (?:question|problem|point)'\n    message: \"Skip the sycophantic opener and start with the substance.\"\n    suggestion: \"Skip the sycophantic opener and start with the substance.\"\n  - pattern: 'that[''’]s a (?:great|fascinating|wonderful|excellent) (?:question|point)'\n    message: \"Skip the sycophantic opener and start with the substance.\"\n    suggestion: \"Skip the sycophantic opener and start with the substance.\"\n---\n",
  "rules/no-throat-clearing.md": "---\nid: no-throat-clearing\nengine: leading\nscope: text\nseverity: error\ndescription: \"Flags throat-clearing openers\"\nrationale: \"Start with the substance. Openers that add no information should be cut.\"\nmessage: \"Cut the throat-clearing and lead with the point.\"\nexamples:\n  - bad: \"Let me think about this. The claim fails.\"\n    good: \"The claim fails.\"\npatterns:\n  - pattern: 'let me think(?: about this)?'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"Cut the throat-clearing and lead with the point.\"\n  - pattern: 'here[''’]s my take'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"Cut the throat-clearing and lead with the point.\"\n  - pattern: 'here[''’]s what i think'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"Cut the throat-clearing and lead with the point.\"\n  - pattern: 'i think it[''’]s worth'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"Cut the throat-clearing and lead with the point.\"\n  - pattern: 'before (?:i|we) (?:begin|start|dive in)'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"Cut the throat-clearing and lead with the point.\"\n  - pattern: '(?i)\\bas we all know\\b'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"State the shared fact directly.\"\n  - pattern: '(?i)\\bit goes without saying\\b'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"Say the point or omit it.\"\n  - pattern: '(?i)\\bbefore diving in\\b'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"Begin with the substance.\"\n  - pattern: '(?i)\\bto set the stage\\b'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"Begin with the relevant fact.\"\n  - pattern: '(?i)\\bfirst,\\s+some context\\b'\n    message: \"Cut the throat-clearing and lead with the point.\"\n    suggestion: \"Give the relevant context without a preface.\"\n---\n",
  "rules/no-weasel-attribution.md": "---\nid: no-weasel-attribution\nengine: phrase\nscope: text\nseverity: warning\ndescription: \"Flags vague attributions without a named source.\"\nrationale: \"Name the source or cut the unsupported claim.\"\nmessage: \"Name the source or cut the claim.\"\nexamples:\n  - bad: \"Experts agree that the policy will fail.\"\n    good: \"The 2024 Treasury report predicts the policy will fail.\"\npatterns:\n  - pattern: '(?i)\\bexperts agree\\b'\n    message: \"Name the source or cut the claim.\"\n    suggestion: \"Name the source or cut the claim.\"\n  - pattern: '(?i)\\bstudies show\\b'\n    message: \"Name the source or cut the claim.\"\n    suggestion: \"Name the study or cut the claim.\"\n  - pattern: '(?i)\\bresearch (?:shows|suggests)\\b'\n    message: \"Name the source or cut the claim.\"\n    suggestion: \"Name the research or cut the claim.\"\n  - pattern: '(?i)\\bmany argue\\b'\n    message: \"Name the source or cut the claim.\"\n    suggestion: \"Name who argues this or cut the claim.\"\n  - pattern: '(?i)\\bwidely regarded as\\b'\n    message: \"Name the source or cut the claim.\"\n    suggestion: \"Name who regards it this way.\"\n  - pattern: '(?i)\\bindustry reports suggest\\b'\n    message: \"Name the source or cut the claim.\"\n    suggestion: \"Name the report or cut the claim.\"\n  - pattern: '(?i)\\bit is widely believed\\b'\n    message: \"Name the source or cut the claim.\"\n    suggestion: \"Name who believes this or cut the claim.\"\n---\n",
  "rules/oxford-comma.md": "---\nid: oxford-comma\nengine: phrase\nscope: text\nseverity: warning\nintent: style\ndescription: \"Flags lists that omit the Oxford comma.\"\nrationale: \"Avoid patterns that can make otherwise clear prose sound formulaic or overworked.\"\nmessage: \"Use the Oxford comma before the final item in a list.\"\nexamples:\n  - bad: \"The parties are Alice, Bob and Carol.\"\n    good: \"The parties are Alice, Bob, and Carol.\"\npatterns:\n  - pattern: '(?i)\\w+,\\s+\\w+(?:\\s+\\w+){0,3}\\s+(?:and|or)\\s+\\w+'\n    message: \"Use the Oxford comma before the final item in a list.\"\n    suggestion: \"Add a comma before the closing “and” or “or”.\"\n---\n",
  "rules/padded-elaboration.md": "---\nid: padded-elaboration\nengine: inferential\nscope: text\nseverity: warning\ndescription: \"Flags sentences that restate the previous point without adding new information.\"\nrationale: \"Restating a point in different words pads the text without informing the reader. Every sentence should add a fact, reason, example, or consequence.\"\nmessage: \"This sentence restates the previous point without adding new information.\"\nexamples:\n  - bad: \"The statute of limitations has expired. In other words, the deadline for filing has passed.\"\n    good: \"The statute of limitations has expired. The plaintiff filed on March 3, sixty days late.\"\ngranularity: paragraph\n---\nFlag a sentence or clause that repeats the point of the sentence before it\nin different words while adding no new fact, reason, number, example,\nexception, or consequence. Padding often starts with \"in other words\",\n\"that is to say\", \"put simply\", \"this means that\", or \"essentially\",\nand then says the same thing again. Do not flag a follow-up sentence\nthat adds something new: a date, an amount, an example, a cause, an\nexception, or what happens next.\n\n## Flag examples\n- \"The statute of limitations has expired. In other words, the deadline for filing has passed.\"\n- \"The contract is unenforceable. Put simply, the parties cannot rely on it because it is not enforceable.\"\n- \"Discovery is complete. That is to say, the discovery process has now finished.\"\n- \"The witness was not credible. Essentially, her testimony could not be believed.\"\n\n## Pass examples\n- \"The statute of limitations has expired. The plaintiff filed on March 3, sixty days late.\"\n- \"The contract is unenforceable. It lacks consideration because neither party promised anything of value.\"\n- \"Discovery is complete. Trial is set for June 9.\"\n- \"The witness was not credible. She gave three different accounts of the accident.\"\n",
  "rules/prefer-concise-phrases.md": "---\nid: prefer-concise-phrases\nengine: phrase\nscope: text\nseverity: suggestion\nintent: style\ndescription: \"Flags padded phrases that a shorter word or nothing replaces.\"\nrationale: \"Orwell's third rule: if it is possible to cut a word out, cut it out. These stock phrases carry no more meaning than the single word that replaces them.\"\nmessage: \"Cut this padded phrase down to a shorter word.\"\nexamples:\n  - bad: \"Due to the fact that the deadline passed, we filed in order to preserve the claim.\"\n    good: \"Because the deadline passed, we filed to preserve the claim.\"\npatterns:\n  - pattern: '(?i)\\bdue to the fact that\\b'\n    message: \"Replace “due to the fact that”.\"\n    suggestion: \"Use “because”.\"\n    fix: \"because\"\n  - pattern: '(?i)\\bin order to\\b'\n    message: \"Replace “in order to”.\"\n    suggestion: \"Use “to”.\"\n    fix: \"to\"\n  - pattern: '(?i)\\bin the event that\\b'\n    message: \"Replace “in the event that”.\"\n    suggestion: \"Use “if”.\"\n    fix: \"if\"\n  - pattern: '(?i)\\bat this point in time\\b'\n    message: \"Replace “at this point in time”.\"\n    suggestion: \"Use “now”.\"\n    fix: \"now\"\n  - pattern: '(?i)\\bat the present time\\b'\n    message: \"Replace “at the present time”.\"\n    suggestion: \"Use “now”.\"\n    fix: \"now\"\n  - pattern: '(?i)\\bfor the purpose of\\b'\n    message: \"Replace “for the purpose of”.\"\n    suggestion: \"Use “to” or “for”.\"\n  - pattern: '(?i)\\bin spite of the fact that\\b'\n    message: \"Replace “in spite of the fact that”.\"\n    suggestion: \"Use “although”.\"\n    fix: \"although\"\n  - pattern: '(?i)\\bwith regard to\\b'\n    message: \"Replace “with regard to”.\"\n    suggestion: \"Use “about”.\"\n    fix: \"about\"\n  - pattern: '(?i)\\bwith respect to\\b'\n    message: \"Replace “with respect to”.\"\n    suggestion: \"Use “about”.\"\n    fix: \"about\"\n  - pattern: '(?i)\\bin relation to\\b'\n    message: \"Replace “in relation to”.\"\n    suggestion: \"Use “about”.\"\n    fix: \"about\"\n  - pattern: '(?i)\\bon a regular basis\\b'\n    message: \"Replace “on a regular basis”.\"\n    suggestion: \"Use “regularly”.\"\n    fix: \"regularly\"\n  - pattern: '(?i)\\bin a timely manner\\b'\n    message: \"Replace “in a timely manner”.\"\n    suggestion: \"Use “promptly”.\"\n    fix: \"promptly\"\n  - pattern: '(?i)\\bin the near future\\b'\n    message: \"Replace “in the near future”.\"\n    suggestion: \"Use “soon”.\"\n    fix: \"soon\"\n  - pattern: '(?i)\\bthe majority of\\b'\n    message: \"Replace “the majority of”.\"\n    suggestion: \"Use “most” or “most of”.\"\n  - pattern: '(?i)\\ba (?:large )?number of\\b'\n    message: \"Replace “a number of”.\"\n    suggestion: \"Use “many” or “some”, or give the count.\"\n  - pattern: '(?i)\\b(?:has the ability to|have the ability to|is able to|are able to)\\b'\n    message: \"Replace this phrase with “can”.\"\n    suggestion: \"Use “can”.\"\n    fix: \"can\"\n  - pattern: '(?i)\\bwhen it comes to\\b'\n    message: \"Cut “when it comes to”.\"\n    suggestion: \"State the subject directly.\"\n  - pattern: '(?i)\\bin today[''’]s world\\b'\n    message: \"Cut “in today’s world”.\"\n    suggestion: \"Start with the point.\"\n  - pattern: '(?i)\\bin the age of\\b'\n    message: \"Cut “in the age of”.\"\n    suggestion: \"Name the present condition directly.\"\n  - pattern: '(?i)\\bin the world of\\b'\n    message: \"Cut “in the world of”.\"\n    suggestion: \"Name the subject directly.\"\n  - pattern: '(?i)\\bthe reality is\\b'\n    message: \"Cut “the reality is”.\"\n    suggestion: \"State the reality directly.\"\n  - pattern: '(?i)\\bthe truth is\\b'\n    message: \"Cut “the truth is”.\"\n    suggestion: \"State the point directly.\"\n  - pattern: '(?i)\\bgoing forward\\b'\n    message: \"Cut “going forward”.\"\n    suggestion: \"State when or what happens next.\"\n  - pattern: '(?i)\\blet[''’]s dive in\\b'\n    message: \"Cut “let’s dive in”.\"\n    suggestion: \"Start with the substance.\"\n  - pattern: '(?i)\\bat its core\\b'\n    message: \"Cut “at its core”.\"\n    suggestion: \"State the central point directly.\"\n  - pattern: '(?i)\\bit[''’]s important to note\\b'\n    message: \"Cut “it’s important to note”.\"\n    suggestion: \"State the important point directly.\"\n---\n",
  "rules/prefer-short-words.md": "---\nid: prefer-short-words\nengine: phrase\nscope: text\nseverity: suggestion\nintent: style\ndescription: \"Flags long words that have a short everyday equivalent.\"\nrationale: \"Orwell's second rule: never use a long word where a short one will do. Swap the long word only where the plain word carries the same meaning; keep terms of art.\"\nmessage: \"Prefer a shorter, plainer word.\"\nexamples:\n  - bad: \"The parties will utilize the platform to facilitate discovery.\"\n    good: \"The parties will use the platform to help discovery.\"\npatterns:\n  - pattern: '(?i)\\butili[sz]e\\b'\n    message: \"Prefer “use” over “utilize”.\"\n    suggestion: \"Use “use”.\"\n    fix: \"use\"\n  - pattern: '(?i)\\butili[sz]ation\\b'\n    message: \"Prefer “use” over “utilization”.\"\n    suggestion: \"Use “use”.\"\n    fix: \"use\"\n  - pattern: '(?i)\\bfacilitate\\b'\n    message: \"Prefer “help” over “facilitate”.\"\n    suggestion: \"Use “help”.\"\n    fix: \"help\"\n  - pattern: '(?i)\\bcommence\\b'\n    message: \"Prefer “start” over “commence”.\"\n    suggestion: \"Use “start” or “begin”.\"\n    fix: \"start\"\n  - pattern: '(?i)\\bterminate\\b'\n    message: \"Prefer “end” over “terminate”.\"\n    suggestion: \"Use “end”.\"\n    fix: \"end\"\n  - pattern: '(?i)\\bendeavou?r\\b'\n    message: \"Prefer “try” over “endeavor”.\"\n    suggestion: \"Use “try”.\"\n    fix: \"try\"\n  - pattern: '(?i)\\bascertain\\b'\n    message: \"Prefer “find out” over “ascertain”.\"\n    suggestion: \"Use “find out”.\"\n    fix: \"find out\"\n  - pattern: '(?i)\\bdemonstrate\\b'\n    message: \"Prefer “show” over “demonstrate”.\"\n    suggestion: \"Use “show”.\"\n    fix: \"show\"\n  - pattern: '(?i)\\bsufficient\\b'\n    message: \"Prefer “enough” over “sufficient”.\"\n    suggestion: \"Use “enough”.\"\n    fix: \"enough\"\n  - pattern: '(?i)\\bnumerous\\b'\n    message: \"Prefer “many” over “numerous”.\"\n    suggestion: \"Use “many”.\"\n    fix: \"many\"\n  - pattern: '(?i)\\bapproximately\\b'\n    message: \"Prefer “about” over “approximately”.\"\n    suggestion: \"Use “about”.\"\n    fix: \"about\"\n  - pattern: '(?i)\\binitiate\\b'\n    message: \"Prefer “start” over “initiate”.\"\n    suggestion: \"Use “start”.\"\n    fix: \"start\"\n  - pattern: '(?i)\\bpurchase\\b'\n    message: \"Prefer “buy” over “purchase”.\"\n    suggestion: \"Use “buy”.\"\n    fix: \"buy\"\n  - pattern: '(?i)\\bmethodology\\b'\n    message: \"Prefer “method” over “methodology”.\"\n    suggestion: \"Use “method”.\"\n    fix: \"method\"\n  - pattern: '(?i)\\bexpedite\\b'\n    message: \"Prefer “speed up” over “expedite”.\"\n    suggestion: \"Use “speed up”.\"\n    fix: \"speed up\"\n  - pattern: '(?i)\\bremainder\\b'\n    message: \"Prefer “rest” over “remainder”.\"\n    suggestion: \"Use “rest”.\"\n    fix: \"rest\"\n  - pattern: '(?i)\\bassist\\b'\n    message: \"Prefer “help” over “assist”.\"\n    suggestion: \"Use “help”.\"\n    fix: \"help\"\n---\n",
  "rules/prefer-spoken-voice.md": "---\nid: prefer-spoken-voice\nengine: inferential\nscope: text\nseverity: warning\n# Judged train smoke (20 AI / 20 human): flagged 0 AI and 2 human rows;\n# human firing makes this a style lint.\nintent: style\ndescription: \"Flags prose that works on the page but not in a spoken explanation.\"\nrationale: \"Clear legal writing can remain precise while using sentences a reader could say aloud.\"\nmessage: \"Rewrite this paragraph in precise language that would also sound natural aloud.\"\nexamples:\n  - bad: \"The foregoing analysis is dispositive with respect to the aforementioned issue in light of the fact that the parties' respective positions are mutually inconsistent.\"\n    good: \"That analysis resolves the issue because the parties take conflicting positions.\"\ngranularity: paragraph\n---\nFlag a paragraph when its meaning depends on clause pile-ups, stacked\nabstractions, or formal connective phrases that would be difficult to say\nand follow aloud. Consider the whole paragraph, not one technical term.\nDo not flag precise legal language merely because it is formal. Do not flag\nnecessary terms of art, statutory language, citations, or a dense sentence\nthat remains clear when read aloud.\n\n## Flag examples\n- \"The foregoing analysis is dispositive with respect to the aforementioned issue in light of the fact that the parties' respective positions are mutually inconsistent.\"\n- \"Notwithstanding the foregoing, the implementation of the contemplated remediation methodology remains subject to further consideration by the appropriate authority.\"\n- \"The determination of whether the provision is applicable necessitates an evaluation of the totality of the circumstances in their aggregate.\"\n- \"In connection with the issue hereinabove discussed, the undersigned respectfully submits that the requested relief is warranted.\"\n\n## Pass examples\n- \"That analysis resolves the issue because the parties take conflicting positions.\"\n- \"The agency must decide whether the proposed remedy complies with the statute.\"\n- \"The court considers the totality of the circumstances.\"\n- \"The brief asks the court to dismiss the claim under Rule 12(b)(6).\"\n",
  "rules/sentence-length.md": "---\nid: sentence-length\nengine: statistical\nscope: text\nseverity: warning\nintent: style\ndescription: \"Flags sentences that are difficult to read.\"\nmessage: \"Sentence is too long; consider shortening it.\"\nmetric: sentence-length\nparams: { max_words: 45 }\nexamples:\n  - bad: \"The court, having reviewed the parties' extensive submissions and the voluminous record developed over three years of contentious litigation, and having heard four hours of oral argument on the competing motions for summary judgment, concludes that genuine disputes of material fact preclude judgment for either side at this stage of the proceedings.\"\n    good: \"The court reviewed the record. Fact disputes preclude summary judgment.\"\n---\n",
  "rules/triad-overuse.md": "---\nid: triad-overuse\nengine: statistical\nscope: text\nseverity: warning\ndescription: \"Flags documents dense with three-part parallel constructions.\"\nrationale: \"One rule-of-three is rhetoric; a document-wide habit of triads is machine cadence. Unlike the per-span core/no-rule-of-three density rule, this measures the whole document's rate.\"\nmessage: \"Three-part constructions recur throughout the document; vary the structure.\"\nmetric: triad-density\nthreshold: 2\ndirection: above\nexamples:\n  - bad: \"The policy is clear, consistent, and fair. It protects employees, customers, and shareholders alike. Compliance requires training, monitoring, and enforcement. Each department must document, review, and certify its procedures. The board will assess progress quarterly, annually, and at each milestone. Managers must plan, supervise, and report their work. Auditors will test controls, trace transactions, and record exceptions. Counsel should identify risks, explain options, and recommend a course. The final report must be accurate, complete, and useful. The committee will review findings, assign owners, and track completion.\"\n    good: \"The policy is clear and fair. It protects employees and customers, and compliance requires training backed by real enforcement. Each department documents its procedures; the board assesses progress quarterly.\"\n---\n",
  "rules/uniform-sentence-rhythm.md": "---\nid: uniform-sentence-rhythm\nengine: statistical\nscope: text\nseverity: warning\ndescription: \"Flags documents whose sentence lengths barely vary.\"\nrationale: \"Human legal prose is bursty — long reasoning sentences sit next to short holdings and citations. Machine prose keeps sentence length uniform, and uniformity is much harder to prompt away than any word list.\"\nmessage: \"Sentence lengths are uniform across the document; vary the rhythm.\"\nmetric: sentence-length-variance\nthreshold: 105\ndirection: below\nexamples:\n  - bad: \"The court reviewed the motion for summary judgment. The parties submitted their briefs on the scheduled date. The record contains several disputed factual questions. The governing standard requires viewing facts in the light most favorable to the nonmoving party. The court finds that genuine disputes preclude judgment here. The motion is therefore denied without prejudice to renewal. The clerk shall enter the order. Counsel shall comply with it.\"\n    good: \"The court reviewed the motion. Both parties briefed it extensively, and the record, including three depositions, two expert reports, and a chain of emails read in incompatible ways, leaves genuine disputes of material fact. Summary judgment is denied.\"\n---\n"
};
